cat > tests/list-order.test.ts <<'EOF'
import assert from "node:assert/strict";
import { DatabaseSync } from "node:sqlite";
import { runInNewContext } from "node:vm";
import { after, before, describe, it } from "node:test";
import { newDbPath, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
}

async function createTask(server: Running, title: string): Promise<void> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
}

async function listTitles(server: Running): Promise<string[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  const { tasks } = (await response.json()) as { tasks: Task[] };
  return tasks.map((task) => task.title);
}

/** Inserts rows straight into the SQLite file, in the given order, bypassing the API. */
function insertRows(dbPath: string, rows: { title: string; createdAt: string }[]): void {
  const db = new DatabaseSync(dbPath);
  db.exec("PRAGMA busy_timeout = 5000");
  const insert = db.prepare(
    "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
  );
  db.exec("BEGIN");
  for (const row of rows) insert.run(row.title, row.createdAt, row.createdAt);
  db.exec("COMMIT");
  db.close();
}

describe("SL-008 list open tasks newest first, with an empty state", () => {
  describe("AC-1: tasks added as A, B, C", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: GET /api/tasks lists C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        await createTask(server, title);
        await new Promise((resolve) => setTimeout(resolve, 5));
      }
      assert.deepEqual(await listTitles(server), ["C", "B", "A"]);
    });

    it("AC-1: creation time decides the order, not the row id", async () => {
      const dbPath = newDbPath();
      const other = await startServer(dbPath);
      try {
        // Saved first but created latest, and the other way round.
        insertRows(dbPath, [
          { title: "newest", createdAt: "2026-03-01T10:00:03.000Z" },
          { title: "oldest", createdAt: "2026-03-01T10:00:01.000Z" },
          { title: "middle", createdAt: "2026-03-01T10:00:02.000Z" },
        ]);
        assert.deepEqual(await listTitles(other), ["newest", "middle", "oldest"]);
      } finally {
        await other.stop();
      }
    });
  });

  describe("AC-2: tasks created within the same instant", () => {
    it("AC-2: the one saved last is listed first, every time", async () => {
      const dbPath = newDbPath();
      const server = await startServer(dbPath);
      try {
        const instant = "2026-03-01T10:00:00.000Z";
        insertRows(dbPath, [
          { title: "first", createdAt: instant },
          { title: "second", createdAt: instant },
          { title: "third", createdAt: instant },
        ]);
        for (let attempt = 0; attempt < 5; attempt++) {
          assert.deepEqual(await listTitles(server), ["third", "second", "first"]);
        }
      } finally {
        await server.stop();
      }
    });

    it("AC-2: ties are broken by save order alongside different instants", async () => {
      const dbPath = newDbPath();
      const server = await startServer(dbPath);
      try {
        insertRows(dbPath, [
          { title: "tie-1", createdAt: "2026-03-01T10:00:02.000Z" },
          { title: "early", createdAt: "2026-03-01T10:00:01.000Z" },
          { title: "tie-2", createdAt: "2026-03-01T10:00:02.000Z" },
        ]);
        assert.deepEqual(await listTitles(server), ["tie-2", "tie-1", "early"]);
      } finally {
        await server.stop();
      }
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    let html: string;
    let script: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: the API answers 200 with an empty list", async () => {
      const response = await fetch(`${server.baseUrl}/api/tasks`);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { tasks: [] });
    });

    it("AC-3: the page has an empty-state element with text", () => {
      assert.match(html, /<[a-z]+[^>]+id=["']empty-state["'][^>]*>\s*[^<\s][^<]*</);
    });

    /** Runs the real page script against a minimal fake DOM and a canned API answer. */
    async function runPage(tasks: { title: string }[]) {
      const element = (id: string) => ({
        id,
        hidden: false,
        value: "",
        children: [] as { textContent: string }[],
        addEventListener() {},
        replaceChildren(...nodes: { textContent: string }[]) {
          this.children = nodes;
        },
      });
      const elements: Record<string, ReturnType<typeof element>> = {};
      for (const id of ["task-form", "task-title", "task-list", "empty-state"]) {
        elements[id] = element(id);
      }
      elements["empty-state"].hidden = true;
      const document = {
        getElementById: (id: string) => elements[id] ?? element(id),
        createElement: () => ({ textContent: "" }),
      };
      const fetch = async () => ({ json: async () => ({ tasks }) });
      runInNewContext(script, { document, fetch });
      await new Promise((resolve) => setTimeout(resolve, 20));
      return elements;
    }

    it("AC-3: with no tasks the page script shows the empty state and no items", async () => {
      const page = await runPage([]);
      assert.equal(page["empty-state"].hidden, false);
      assert.equal(page["task-list"].children.length, 0);
    });

    it("AC-3: with tasks the page script hides the empty state", async () => {
      const page = await runPage([{ title: "A" }]);
      assert.equal(page["empty-state"].hidden, true);
      assert.equal(page["task-list"].children.length, 1);
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    it("AC-4: 20 sequential GET /api/tasks have p95 under 100 ms and a body under 400000 bytes", async () => {
      const dbPath = newDbPath();
      const server = await startServer(dbPath);
      try {
        const start = Date.parse("2026-03-01T10:00:00.000Z");
        insertRows(
          dbPath,
          Array.from({ length: 1000 }, (_, i) => ({
            title: `Task ${i} ${"x".repeat(100)}`,
            createdAt: new Date(start + i * 1000).toISOString(),
          })),
        );

        const timings: number[] = [];
        let size = 0;
        for (let i = 0; i < 20; i++) {
          const began = performance.now();
          const response = await fetch(`${server.baseUrl}/api/tasks`);
          const body = await response.text();
          timings.push(performance.now() - began);
          size = Buffer.byteLength(body);
          assert.equal(response.status, 200);
        }
        timings.sort((a, b) => a - b);
        const p95 = timings[Math.ceil(timings.length * 0.95) - 1];
        assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
        assert.ok(size < 400000, `body was ${size} bytes`);

        const titles = await listTitles(server);
        assert.equal(titles.length, 1000);
        assert.ok(titles[0].startsWith("Task 999 "));
      } finally {
        await server.stop();
      }
    });
  });
});
